  SELECT RAISE(ABORT, 'P0001:Tipo de vínculo inválido. Use fixo, diarista ou freelancer.') WHERE NEW.employment_type IS NOT NULL AND NEW.employment_type NOT IN ('fixo','diarista','freelancer');
END;
