CREATE TRIGGER IF NOT EXISTS "trg_personal_expenses_reversed_guard__update" BEFORE UPDATE ON "personal_expenses" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Lancamento estornado nao pode ser alterado') WHERE EXISTS (SELECT 1 FROM personal_expenses e WHERE e.reverses_id = NEW.id);
END;
CREATE TRIGGER IF NOT EXISTS "trg_personal_expenses_reversal_validate__insert" BEFORE INSERT ON "personal_expenses" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Lancamento original inexistente') WHERE NEW.reverses_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM personal_expenses WHERE id = NEW.reverses_id);
  SELECT RAISE(ABORT, 'P0001:Estorno deve pertencer ao mesmo proprietario') WHERE NEW.reverses_id IS NOT NULL AND (SELECT owner_id FROM personal_expenses WHERE id = NEW.reverses_id) <> NEW.owner_id;
  SELECT RAISE(ABORT, 'P0001:Nao e permitido estornar um estorno') WHERE NEW.reverses_id IS NOT NULL AND (SELECT reverses_id FROM personal_expenses WHERE id = NEW.reverses_id) IS NOT NULL;
  SELECT RAISE(ABORT, 'P0001:Estorno deve ter natureza oposta ao lancamento original') WHERE NEW.reverses_id IS NOT NULL AND (SELECT kind FROM personal_expenses WHERE id = NEW.reverses_id) = NEW.kind;
  SELECT RAISE(ABORT, 'P0001:Estorno deve ter o mesmo valor do lancamento original') WHERE NEW.reverses_id IS NOT NULL AND (SELECT amount_cents FROM personal_expenses WHERE id = NEW.reverses_id) <> NEW.amount_cents;
END;
CREATE TRIGGER IF NOT EXISTS "trg_personal_expenses_reversal_validate__update" BEFORE UPDATE ON "personal_expenses" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Lancamento original inexistente') WHERE NEW.reverses_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM personal_expenses WHERE id = NEW.reverses_id);
  SELECT RAISE(ABORT, 'P0001:Estorno deve pertencer ao mesmo proprietario') WHERE NEW.reverses_id IS NOT NULL AND (SELECT owner_id FROM personal_expenses WHERE id = NEW.reverses_id) <> NEW.owner_id;
  SELECT RAISE(ABORT, 'P0001:Nao e permitido estornar um estorno') WHERE NEW.reverses_id IS NOT NULL AND (SELECT reverses_id FROM personal_expenses WHERE id = NEW.reverses_id) IS NOT NULL;
  SELECT RAISE(ABORT, 'P0001:Estorno deve ter natureza oposta ao lancamento original') WHERE NEW.reverses_id IS NOT NULL AND (SELECT kind FROM personal_expenses WHERE id = NEW.reverses_id) = NEW.kind;
  SELECT RAISE(ABORT, 'P0001:Estorno deve ter o mesmo valor do lancamento original') WHERE NEW.reverses_id IS NOT NULL AND (SELECT amount_cents FROM personal_expenses WHERE id = NEW.reverses_id) <> NEW.amount_cents;
  SELECT RAISE(ABORT, 'P0001:Vinculo de estorno nao pode ser alterado') WHERE NEW.reverses_id IS NOT NULL AND OLD.reverses_id IS NOT NEW.reverses_id;
  SELECT RAISE(ABORT, 'P0001:Vinculo de estorno nao pode ser removido') WHERE NEW.reverses_id IS NULL AND OLD.reverses_id IS NOT NULL;
END;
