CREATE TRIGGER IF NOT EXISTS "trg_validate_interstate_transport__insert" BEFORE INSERT ON "interstate_transports" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Status invalido. Use planned, in_transit, completed ou cancelled.') WHERE NEW.status IS NULL OR NEW.status NOT IN ('planned','in_transit','completed','cancelled');
  SELECT RAISE(ABORT, 'P0001:Quilometragem, consumo e capacidade nao podem ser negativos.') WHERE NEW.distance_km < 0 OR NEW.fuel_consumption_kmpl < 0 OR (NEW.vehicle_capacity_kg IS NOT NULL AND NEW.vehicle_capacity_kg < 0);
  SELECT RAISE(ABORT, 'P0001:Valores monetarios nao podem ser negativos.') WHERE NEW.fuel_price_cents < 0 OR NEW.fuel_cost_cents < 0 OR NEW.toll_cents < 0 OR NEW.lodging_cents < 0 OR NEW.meals_cents < 0 OR NEW.daily_rate_cents < 0 OR NEW.maintenance_cents < 0 OR NEW.freight_cents < 0 OR NEW.advance_cents < 0 OR NEW.extra_cents < 0 OR NEW.revenue_cents < 0;
  SELECT RAISE(ABORT, 'P0001:legs deve ser um array JSON.') WHERE json_type(NEW.legs) <> 'array';
  SELECT RAISE(ABORT, 'P0001:helpers deve ser um array JSON.') WHERE json_type(NEW.helpers) <> 'array';
  SELECT RAISE(ABORT, 'P0001:A data de chegada nao pode ser anterior a data de saida.') WHERE NEW.arrival_date IS NOT NULL AND NEW.arrival_date < NEW.transport_date;
  SELECT RAISE(ABORT, 'P0001:A data de retorno nao pode ser anterior a data de saida.') WHERE NEW.expected_return_date IS NOT NULL AND NEW.expected_return_date < NEW.transport_date;
END;
CREATE TRIGGER IF NOT EXISTS "trg_validate_interstate_transport__update" BEFORE UPDATE ON "interstate_transports" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Status invalido. Use planned, in_transit, completed ou cancelled.') WHERE NEW.status IS NOT OLD.status AND (NEW.status IS NULL OR NEW.status NOT IN ('planned','in_transit','completed','cancelled'));
  SELECT RAISE(ABORT, 'P0001:Quilometragem, consumo e capacidade nao podem ser negativos.') WHERE NEW.distance_km < 0 OR NEW.fuel_consumption_kmpl < 0 OR (NEW.vehicle_capacity_kg IS NOT NULL AND NEW.vehicle_capacity_kg < 0);
  SELECT RAISE(ABORT, 'P0001:Valores monetarios nao podem ser negativos.') WHERE NEW.fuel_price_cents < 0 OR NEW.fuel_cost_cents < 0 OR NEW.toll_cents < 0 OR NEW.lodging_cents < 0 OR NEW.meals_cents < 0 OR NEW.daily_rate_cents < 0 OR NEW.maintenance_cents < 0 OR NEW.freight_cents < 0 OR NEW.advance_cents < 0 OR NEW.extra_cents < 0 OR NEW.revenue_cents < 0;
  SELECT RAISE(ABORT, 'P0001:legs deve ser um array JSON.') WHERE json_type(NEW.legs) <> 'array';
  SELECT RAISE(ABORT, 'P0001:helpers deve ser um array JSON.') WHERE json_type(NEW.helpers) <> 'array';
  SELECT RAISE(ABORT, 'P0001:A data de chegada nao pode ser anterior a data de saida.') WHERE NEW.arrival_date IS NOT NULL AND NEW.arrival_date < NEW.transport_date;
  SELECT RAISE(ABORT, 'P0001:A data de retorno nao pode ser anterior a data de saida.') WHERE NEW.expected_return_date IS NOT NULL AND NEW.expected_return_date < NEW.transport_date;
END;
CREATE TRIGGER IF NOT EXISTS "trg_fiscal_document_guard__insert" BEFORE INSERT ON "fiscal_documents" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Novo documento só pode nascer como rascunho ou validado. Autorização ocorre por transição auditada.') WHERE NEW.status NOT IN ('rascunho','validado');
  SELECT RAISE(ABORT, 'P0001:Chave, protocolo e data de autorização não podem ser informados na criação.') WHERE NEW.protocol_number IS NOT NULL OR NEW.access_key IS NOT NULL OR NEW.authorized_at IS NOT NULL;
END;
CREATE TRIGGER IF NOT EXISTS "trg_fiscal_document_guard__update" BEFORE UPDATE ON "fiscal_documents" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Transição de situação inválida.') WHERE NEW.status IS NOT OLD.status AND NOT (CASE OLD.status WHEN 'rascunho' THEN NEW.status IN ('validado', 'cancelado') WHEN 'validado' THEN NEW.status IN ('rascunho', 'aguardando_assinatura', 'enviado', 'cancelado') WHEN 'aguardando_assinatura' THEN NEW.status IN ('validado', 'enviado', 'rejeitado', 'cancelado') WHEN 'enviado' THEN NEW.status IN ('autorizado', 'rejeitado', 'cancelado') WHEN 'rejeitado' THEN NEW.status IN ('rascunho', 'validado', 'enviado', 'cancelado') WHEN 'autorizado' THEN NEW.status IN ('cancelado', 'encerrado') ELSE 0 END);
  SELECT RAISE(ABORT, 'P0001:Autorização exige chave de acesso com 44 dígitos.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND (NEW.access_key IS NULL OR NOT (length(NEW.access_key) = 44 AND NEW.access_key NOT GLOB '*[^0-9]*'));
  SELECT RAISE(ABORT, 'P0001:Autorização exige número de protocolo real da SEFAZ.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND COALESCE(NEW.protocol_number, '') = '';
  SELECT RAISE(ABORT, 'P0001:Autorização exige data/hora de autorização.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND NEW.authorized_at IS NULL;
  SELECT RAISE(ABORT, 'P0001:Autorização exige XML autorizado armazenado com hash SHA-256 válido.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND (COALESCE(NEW.xml_path, '') = '' OR NEW.xml_sha256 IS NULL OR NOT (length(NEW.xml_sha256) = 64 AND NEW.xml_sha256 NOT GLOB '*[^0-9a-f]*'));
  SELECT RAISE(ABORT, 'P0001:Autorização exige origem válida (sefaz_provider ou external_import).') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND (NEW.authorization_source IS NULL OR NEW.authorization_source NOT IN ('sefaz_provider','external_import'));
  SELECT RAISE(ABORT, 'P0001:Ambiente não pode mudar durante a autorização.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND NEW.environment IS NOT OLD.environment;
  SELECT RAISE(ABORT, 'P0001:Origem da autorização incoerente com a origem do documento.') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'autorizado' AND NEW.authorization_source = 'external_import' AND NEW.source <> 'external_import';
  SELECT RAISE(ABORT, 'P0001:Encerramento aplica-se somente ao MDF-e (modelo 58).') WHERE NEW.status IS NOT OLD.status AND NEW.status = 'encerrado' AND NEW.model <> '58';
  SELECT RAISE(ABORT, 'P0001:Documento autorizado é imutável. Use cancelamento ou encerramento.') WHERE OLD.status = 'autorizado' AND (NEW.access_key IS NOT OLD.access_key OR NEW.protocol_number IS NOT OLD.protocol_number OR NEW.authorized_at IS NOT OLD.authorized_at OR NEW.xml_sha256 IS NOT OLD.xml_sha256 OR NEW.xml_path IS NOT OLD.xml_path OR NEW.environment IS NOT OLD.environment OR NEW.model IS NOT OLD.model OR NEW.total_document_cents IS NOT OLD.total_document_cents);
END;
