CREATE TRIGGER IF NOT EXISTS "trg_finance_title_guard__update" BEFORE UPDATE ON "finance_titles" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Título está fechado e não pode ter dados materiais alterados.') WHERE OLD.status IN ('pago','estornado','cancelado') AND (NEW.total_amount IS NOT OLD.total_amount OR NEW.kind IS NOT OLD.kind OR NEW.client_id IS NOT OLD.client_id OR NEW.event_id IS NOT OLD.event_id OR NEW.contract_id IS NOT OLD.contract_id OR NEW.quote_id IS NOT OLD.quote_id OR NEW.supplier_name IS NOT OLD.supplier_name OR NEW.source_type IS NOT OLD.source_type OR NEW.source_id IS NOT OLD.source_id);
  SELECT RAISE(ABORT, 'P0001:Transição de status inválida.') WHERE NEW.status IS NOT OLD.status AND NOT (CASE OLD.status WHEN 'rascunho' THEN NEW.status IN ('pendente', 'cancelado') WHEN 'pendente' THEN NEW.status IN ('aprovado', 'pago', 'cancelado') WHEN 'aprovado' THEN NEW.status IN ('pago', 'cancelado') WHEN 'pago' THEN NEW.status IN ('estornado') ELSE 0 END);
END;
