  SELECT RAISE(ABORT, 'P0001:Pagamentos são imutáveis. Registre um estorno.');
END;
CREATE TRIGGER IF NOT EXISTS "trg_forbid_delete_finance_payments__delete" BEFORE DELETE ON "finance_payments" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Exclusão não permitida em finance_payments. Use cancelamento ou estorno.');
END;
CREATE TRIGGER IF NOT EXISTS "trg_finance_payment_guard__insert" BEFORE INSERT ON "finance_payments" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Título inexistente.') WHERE NOT EXISTS (SELECT 1 FROM finance_titles WHERE id = NEW.title_id);
  SELECT RAISE(ABORT, 'P0001:Parcela inválida para este título.') WHERE NEW.installment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM finance_installments i WHERE i.id = NEW.installment_id AND i.title_id = NEW.title_id);
  SELECT RAISE(ABORT, 'P0001:Estorno exige o pagamento de origem.') WHERE NEW.is_reversal AND NEW.reverses_payment_id IS NULL;
  SELECT RAISE(ABORT, 'P0001:Pagamento de origem inexistente.') WHERE NEW.is_reversal AND NOT EXISTS (SELECT 1 FROM finance_payments WHERE id = NEW.reverses_payment_id);
  SELECT RAISE(ABORT, 'P0001:Não é possível estornar um estorno.') WHERE NEW.is_reversal AND (SELECT is_reversal FROM finance_payments WHERE id = NEW.reverses_payment_id);
  SELECT RAISE(ABORT, 'P0001:O estorno deve referenciar o mesmo título e parcela do pagamento original.') WHERE NEW.is_reversal AND EXISTS (SELECT 1 FROM finance_payments o WHERE o.id = NEW.reverses_payment_id AND (o.title_id <> NEW.title_id OR o.installment_id IS NOT NEW.installment_id));
  SELECT RAISE(ABORT, 'P0001:O estorno deve ser pelo valor integral do pagamento original.') WHERE NEW.is_reversal AND (SELECT amount FROM finance_payments WHERE id = NEW.reverses_payment_id) <> NEW.amount;
  SELECT RAISE(ABORT, 'P0001:Este pagamento já possui estorno.') WHERE NEW.is_reversal AND EXISTS (SELECT 1 FROM finance_payments WHERE reverses_payment_id = NEW.reverses_payment_id);
  SELECT RAISE(ABORT, 'P0001:Pagamento normal não pode referenciar estorno.') WHERE NOT NEW.is_reversal AND NEW.reverses_payment_id IS NOT NULL;
  SELECT RAISE(ABORT, 'P0001:Título não aceita pagamentos.') WHERE NOT NEW.is_reversal AND (SELECT status FROM finance_titles WHERE id = NEW.title_id) IN ('cancelado','estornado');
  SELECT RAISE(ABORT, 'P0001:Parcela cancelada não aceita pagamentos.') WHERE NOT NEW.is_reversal AND NEW.installment_id IS NOT NULL AND (SELECT status FROM finance_installments WHERE id = NEW.installment_id) = 'cancelado';
  SELECT RAISE(ABORT, 'P0001:Não há saldo em aberto para receber pagamento.') WHERE NOT NEW.is_reversal AND (CASE WHEN NEW.installment_id IS NOT NULL THEN (SELECT amount FROM finance_installments WHERE id = NEW.installment_id) - (SELECT COALESCE(SUM(CASE WHEN is_reversal THEN -amount ELSE amount END), 0) FROM finance_payments WHERE installment_id = NEW.installment_id) ELSE (SELECT total_amount FROM finance_titles WHERE id = NEW.title_id) - (SELECT COALESCE(SUM(CASE WHEN is_reversal THEN -amount ELSE amount END), 0) FROM finance_payments WHERE title_id = NEW.title_id) END) <= 0;
  SELECT RAISE(ABORT, 'P0001:Pagamento excede o saldo em aberto.') WHERE NOT NEW.is_reversal AND NEW.amount > (CASE WHEN NEW.installment_id IS NOT NULL THEN (SELECT amount FROM finance_installments WHERE id = NEW.installment_id) - (SELECT COALESCE(SUM(CASE WHEN is_reversal THEN -amount ELSE amount END), 0) FROM finance_payments WHERE installment_id = NEW.installment_id) ELSE (SELECT total_amount FROM finance_titles WHERE id = NEW.title_id) - (SELECT COALESCE(SUM(CASE WHEN is_reversal THEN -amount ELSE amount END), 0) FROM finance_payments WHERE title_id = NEW.title_id) END) + 0.005;
END;
