CREATE TRIGGER IF NOT EXISTS "trg_finance_installment_guard__update" BEFORE UPDATE ON "finance_installments" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Parcela está fechada e não pode ter valor/vínculo alterado.') WHERE OLD.status IN ('pago','cancelado') AND (NEW.amount IS NOT OLD.amount OR NEW.title_id IS NOT OLD.title_id OR NEW.number IS NOT OLD.number);
  SELECT RAISE(ABORT, 'P0001:Transição de status inválida na parcela.') WHERE NEW.status IS NOT OLD.status AND NOT (CASE OLD.status WHEN 'pendente' THEN NEW.status IN ('parcial', 'pago', 'cancelado') WHEN 'parcial' THEN NEW.status IN ('pago', 'cancelado') WHEN 'pago' THEN NEW.status IN ('parcial', 'pendente') ELSE 0 END);
