BEGIN
  UPDATE event_equipment SET status = 'returned', updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE event_id = NEW.id AND status IN ('confirmed', 'active', 'pending');
END;
CREATE TRIGGER IF NOT EXISTS "update_event_totals_trigger__insert" AFTER INSERT ON "event_expenses" FOR EACH ROW
BEGIN
  UPDATE events SET total_expenses = (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = NEW.event_id), profit_margin = total_budget - (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = NEW.event_id), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = NEW.event_id;
END;
