BEGIN
  UPDATE events SET total_expenses = (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = NEW.event_id), profit_margin = total_budget - (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = NEW.event_id), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = NEW.event_id;
  UPDATE events SET total_expenses = (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = OLD.event_id), profit_margin = total_budget - (SELECT COALESCE(SUM(total_price), 0) FROM event_expenses WHERE event_id = OLD.event_id), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = OLD.event_id AND OLD.event_id IS NOT NEW.event_id;
END;
