CREATE TRIGGER IF NOT EXISTS "validate_daily_rate_fields_trg__insert" BEFORE INSERT ON "daily_rates" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Presença inválida. Use prevista, presente, falta, substituido ou cancelada.') WHERE NEW.attendance_status IS NOT NULL AND NEW.attendance_status NOT IN ('prevista','presente','falta','substituido','cancelada');
  SELECT RAISE(ABORT, 'P0001:Status de pagamento inválido. Use pendente, aprovado, pago ou cancelado.') WHERE NEW.payment_status IS NOT NULL AND NEW.payment_status NOT IN ('pendente','aprovado','pago','cancelado');
  SELECT RAISE(ABORT, 'P0001:Hora extra não pode ser negativa.') WHERE COALESCE(NEW.overtime_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Alimentação não pode ser negativa.') WHERE COALESCE(NEW.food_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Transporte não pode ser negativo.') WHERE COALESCE(NEW.transport_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Hospedagem não pode ser negativa.') WHERE COALESCE(NEW.lodging_amount, 0) < 0;
END;
CREATE TRIGGER IF NOT EXISTS "validate_daily_rate_fields_trg__update" BEFORE UPDATE ON "daily_rates" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Presença inválida. Use prevista, presente, falta, substituido ou cancelada.') WHERE NEW.attendance_status IS NOT NULL AND NEW.attendance_status NOT IN ('prevista','presente','falta','substituido','cancelada');
  SELECT RAISE(ABORT, 'P0001:Status de pagamento inválido. Use pendente, aprovado, pago ou cancelado.') WHERE NEW.payment_status IS NOT NULL AND NEW.payment_status NOT IN ('pendente','aprovado','pago','cancelado');
  SELECT RAISE(ABORT, 'P0001:Hora extra não pode ser negativa.') WHERE COALESCE(NEW.overtime_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Alimentação não pode ser negativa.') WHERE COALESCE(NEW.food_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Transporte não pode ser negativo.') WHERE COALESCE(NEW.transport_amount, 0) < 0;
  SELECT RAISE(ABORT, 'P0001:Hospedagem não pode ser negativa.') WHERE COALESCE(NEW.lodging_amount, 0) < 0;
END;
