  DELETE FROM event_expenses WHERE reference_type = 'daily_rate' AND reference_id = OLD.id;
END;
CREATE TRIGGER IF NOT EXISTS "create_event_expense_from_daily_rate_trigger__insert" AFTER INSERT ON "daily_rates" FOR EACH ROW
BEGIN
  INSERT INTO event_expenses (event_id, category, description, quantity, unit_price, total_price, expense_date, reference_type, reference_id, created_by) SELECT NEW.event_id, 'Diárias', 'Diária - ' || NEW.worker_name, 1, NEW.amount, NEW.amount, NEW.date, 'daily_rate', NEW.id, NEW.created_by WHERE NEW.event_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM event_expenses WHERE reference_type = 'daily_rate' AND reference_id = NEW.id);
END;
CREATE TRIGGER IF NOT EXISTS "record_contract_history__insert" AFTER INSERT ON "contracts" FOR EACH ROW
BEGIN
  INSERT INTO contract_history (contract_id, action, from_status, to_status, actor_id, actor_name) VALUES (NEW.id, 'created', NULL, NEW.status, (SELECT v FROM _ctx WHERE k = 'uid'), (SELECT name FROM user_credentials WHERE id = (SELECT v FROM _ctx WHERE k = 'uid')));
END;
CREATE TRIGGER IF NOT EXISTS "record_contract_history__update" AFTER UPDATE ON "contracts" FOR EACH ROW WHEN json_insert(json_object('id', OLD."id", 'contract_number', OLD."contract_number", 'client_name', OLD."client_name", 'client_email', OLD."client_email", 'client_phone', OLD."client_phone", 'client_document', OLD."client_document", 'service_description', OLD."service_description", 'start_date', OLD."start_date", 'end_date', OLD."end_date", 'total_value', OLD."total_value", 'payment_terms', OLD."payment_terms", 'status', OLD."status", 'created_at', OLD."created_at", 'updated_at', OLD."updated_at", 'created_by', OLD."created_by"), '$.template_id', OLD."template_id", '$.template_version', OLD."template_version", '$.template_name', OLD."template_name", '$.sections_snapshot', json(OLD."sections_snapshot"), '$.details', json(OLD."details"), '$.client_id', OLD."client_id", '$.event_id', OLD."event_id", '$.quote_id', OLD."quote_id", '$.source_quote_number', OLD."source_quote_number", '$.sent_at', OLD."sent_at", '$.signed_at', OLD."signed_at", '$.cancelled_at', OLD."cancelled_at", '$.locked', CASE WHEN OLD."locked" IS NULL THEN NULL WHEN OLD."locked" THEN json('true') ELSE json('false') END, '$.updated_by', OLD."updated_by") IS NOT json_insert(json_object('id', NEW."id", 'contract_number', NEW."contract_number", 'client_name', NEW."client_name", 'client_email', NEW."client_email", 'client_phone', NEW."client_phone", 'client_document', NEW."client_document", 'service_description', NEW."service_description", 'start_date', NEW."start_date", 'end_date', NEW."end_date", 'total_value', NEW."total_value", 'payment_terms', NEW."payment_terms", 'status', NEW."status", 'created_at', NEW."created_at", 'updated_at', NEW."updated_at", 'created_by', NEW."created_by"), '$.template_id', NEW."template_id", '$.template_version', NEW."template_version", '$.template_name', NEW."template_name", '$.sections_snapshot', json(NEW."sections_snapshot"), '$.details', json(NEW."details"), '$.client_id', NEW."client_id", '$.event_id', NEW."event_id", '$.quote_id', NEW."quote_id", '$.source_quote_number', NEW."source_quote_number", '$.sent_at', NEW."sent_at", '$.signed_at', NEW."signed_at", '$.cancelled_at', NEW."cancelled_at", '$.locked', CASE WHEN NEW."locked" IS NULL THEN NULL WHEN NEW."locked" THEN json('true') ELSE json('false') END, '$.updated_by', NEW."updated_by")
BEGIN
  INSERT INTO contract_history (contract_id, action, from_status, to_status, actor_id, actor_name, changes) VALUES (NEW.id, CASE WHEN NEW.status IS NOT OLD.status THEN 'status_changed' ELSE 'updated' END, OLD.status, NEW.status, (SELECT v FROM _ctx WHERE k = 'uid'), (SELECT name FROM user_credentials WHERE id = (SELECT v FROM _ctx WHERE k = 'uid')), json_object('total_value', NEW.total_value, 'template_version', NEW.template_version, 'locked', CASE WHEN NEW.locked IS NULL THEN NULL WHEN NEW.locked THEN json('true') ELSE json('false') END));
END;
CREATE TRIGGER IF NOT EXISTS "enforce_signed_contract_immutability__update" BEFORE UPDATE ON "contracts" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Contrato assinado não pode ser destravado.') WHERE (COALESCE(OLD.locked, 0) OR OLD.status = 'assinado') AND COALESCE(NEW.locked, 0) = 0;
  SELECT RAISE(ABORT, 'P0001:Contrato assinado não pode ter seu conteúdo alterado. Somente status, anexos e metadados autorizados.') WHERE (COALESCE(OLD.locked, 0) OR OLD.status = 'assinado') AND (NEW.client_name IS NOT OLD.client_name OR NEW.client_document IS NOT OLD.client_document OR NEW.client_email IS NOT OLD.client_email OR NEW.client_phone IS NOT OLD.client_phone OR NEW.service_description IS NOT OLD.service_description OR NEW.start_date IS NOT OLD.start_date OR NEW.end_date IS NOT OLD.end_date OR NEW.total_value IS NOT OLD.total_value OR NEW.payment_terms IS NOT OLD.payment_terms OR json(NEW.sections_snapshot) IS NOT json(OLD.sections_snapshot) OR json(NEW.details) IS NOT json(OLD.details) OR NEW.template_id IS NOT OLD.template_id OR NEW.template_version IS NOT OLD.template_version OR NEW.template_name IS NOT OLD.template_name OR NEW.contract_number IS NOT OLD.contract_number OR NEW.client_id IS NOT OLD.client_id OR NEW.event_id IS NOT OLD.event_id OR NEW.quote_id IS NOT OLD.quote_id OR NEW.signed_at IS NOT OLD.signed_at);
END;
