CREATE TRIGGER IF NOT EXISTS "trg_prevent_duplicate_bank_transaction_reference__insert" BEFORE INSERT ON "bank_transactions" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Já existe lançamento bancário para esta origem.') WHERE NEW.reference_type IS NOT NULL AND NEW.reference_id IS NOT NULL AND EXISTS (SELECT 1 FROM bank_transactions bt WHERE bt.reference_type = NEW.reference_type AND bt.reference_id = NEW.reference_id AND bt.id <> NEW.id);
END;
CREATE TRIGGER IF NOT EXISTS "trg_prevent_duplicate_bank_transaction_reference__update" BEFORE UPDATE OF "reference_type", "reference_id" ON "bank_transactions" FOR EACH ROW WHEN NOT (NEW.reference_type IS OLD.reference_type AND NEW.reference_id IS OLD.reference_id)
BEGIN
  SELECT RAISE(ABORT, 'P0001:Já existe lançamento bancário para esta origem.') WHERE NEW.reference_type IS NOT NULL AND NEW.reference_id IS NOT NULL AND EXISTS (SELECT 1 FROM bank_transactions bt WHERE bt.reference_type = NEW.reference_type AND bt.reference_id = NEW.reference_id AND bt.id <> NEW.id);
END;
CREATE TRIGGER IF NOT EXISTS "trg_enforce_bank_period_closing__insert" BEFORE INSERT ON "bank_transactions" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Período já fechado para esta conta na data informada.') WHERE EXISTS (SELECT 1 FROM bank_account_closings c WHERE c.bank_account_id = NEW.bank_account_id AND NEW.transaction_date <= c.closed_through);
END;
CREATE TRIGGER IF NOT EXISTS "trg_enforce_bank_period_closing__update" BEFORE UPDATE ON "bank_transactions" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Período já fechado para esta conta até a data do lançamento original.') WHERE EXISTS (SELECT 1 FROM bank_account_closings c WHERE c.bank_account_id = OLD.bank_account_id AND OLD.transaction_date <= c.closed_through);
  SELECT RAISE(ABORT, 'P0001:Período já fechado para esta conta na data informada.') WHERE EXISTS (SELECT 1 FROM bank_account_closings c WHERE c.bank_account_id = NEW.bank_account_id AND NEW.transaction_date <= c.closed_through);
END;
CREATE TRIGGER IF NOT EXISTS "trg_enforce_bank_period_closing__delete" BEFORE DELETE ON "bank_transactions" FOR EACH ROW
BEGIN
  SELECT RAISE(ABORT, 'P0001:Período já fechado para esta conta até a data do lançamento original.') WHERE EXISTS (SELECT 1 FROM bank_account_closings c WHERE c.bank_account_id = OLD.bank_account_id AND OLD.transaction_date <= c.closed_through);
END;
