CREATE TRIGGER IF NOT EXISTS "auto_update_balance_on_transaction__insert" AFTER INSERT ON "bank_transactions" FOR EACH ROW
BEGIN
  UPDATE bank_accounts SET balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = NEW.bank_account_id), 2), current_balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = NEW.bank_account_id), 2), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = NEW.bank_account_id;
END;
CREATE TRIGGER IF NOT EXISTS "auto_update_balance_on_transaction__delete" AFTER DELETE ON "bank_transactions" FOR EACH ROW
BEGIN
  UPDATE bank_accounts SET balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = OLD.bank_account_id), 2), current_balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = OLD.bank_account_id), 2), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = OLD.bank_account_id;
END;
CREATE TRIGGER IF NOT EXISTS "auto_update_balance_on_transaction__update" AFTER UPDATE ON "bank_transactions" FOR EACH ROW
BEGIN
  UPDATE bank_accounts SET balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = NEW.bank_account_id), 2), current_balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = NEW.bank_account_id), 2), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = NEW.bank_account_id;
  UPDATE bank_accounts SET balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = OLD.bank_account_id), 2), current_balance = round((SELECT COALESCE(SUM(CASE WHEN transaction_type = 'income' THEN amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN transaction_type = 'expense' THEN amount ELSE 0 END), 0) FROM bank_transactions WHERE bank_account_id = OLD.bank_account_id), 2), updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE id = OLD.bank_account_id AND OLD.bank_account_id IS NOT NEW.bank_account_id;
END;
